
const A={"backgrounds/codex_yard_day_3840x1080.png": "data:image/png;base64,", "backgrounds/codex_yard_evening_3840x1080.png": "data:image/png;base64,", "result/codex_castle_defeat.svg": "data:image/svg+xml;base64,", "result/codex_castle_example.svg": "data:image/svg+xml;base64,", "result/codex_castle_intact.svg": "data:image/svg+xml;base64,", "result/codex_portrait_archer.png": "data:image/png;base64,", "result/codex_portrait_cannon.png": "data:image/png;base64,", "result/codex_portrait_gunner.png": "data:image/png;base64,", "result/codex_portrait_hero.png": "data:image/png;base64,", "result/codex_portrait_wizard.png": "data:image/png;base64,", "result/codex_result_defeat_1920x1080.png": "data:image/png;base64,", "result/codex_result_victory_1920x1080.png": "data:image/png;base64,", "result/codex_wall_east_broken.svg": "data:image/svg+xml;base64,", "result/codex_wall_east_cracked.svg": "data:image/svg+xml;base64,", "result/codex_wall_east_intact.svg": "data:image/svg+xml;base64,", "result/codex_wall_north_broken.svg": "data:image/svg+xml;base64,", "result/codex_wall_north_cracked.svg": "data:image/svg+xml;base64,", "result/codex_wall_north_intact.svg": "data:image/svg+xml;base64,", "result/codex_wall_south_broken.svg": "data:image/svg+xml;base64,", "result/codex_wall_south_cracked.svg": "data:image/svg+xml;base64,", "result/codex_wall_south_intact.svg": "data:image/svg+xml;base64,", "result/codex_wall_west_broken.svg": "data:image/svg+xml;base64,", "result/codex_wall_west_cracked.svg": "data:image/svg+xml;base64,", "result/codex_wall_west_intact.svg": "data:image/svg+xml;base64,", "stations/codex_barracks.png": "data:image/png;base64,", "stations/codex_repair.png": "data:image/png;base64,", "stations/codex_stairs.png": "data:image/png;base64,", "stations/codex_workshop.png": "data:image/png;base64,", "ui/codex_interact_e.svg": "data:image/svg+xml;base64,", "ui/codex_name_barracks.svg": "data:image/svg+xml;base64,", "ui/codex_name_repair.svg": "data:image/svg+xml;base64,", "ui/codex_name_stairs.svg": "data:image/svg+xml;base64,", "ui/codex_name_workshop.svg": "data:image/svg+xml;base64,", "ui/codex_ribbon_defeat.svg": "data:image/svg+xml;base64,", "ui/codex_ribbon_victory.svg": "data:image/svg+xml;base64,"};const names=['성벽 수리 자리','병영','함정 공방','성벽 계단'];let x=13,near=0,held={};const yard=document.getElementById('yard'),hero=document.getElementById('hero'),prompt=document.getElementById('prompt');
document.documentElement.style.setProperty('--hero','url("data:image/png;base64,")');
function time(t){yard.style.backgroundImage='url("'+A['backgrounds/codex_yard_'+t+'_3840x1080.png']+'")';['day','evening'].forEach(n=>document.getElementById(n).setAttribute('aria-pressed',n===t));}time('day');
document.getElementById('day').onclick=()=>time('day');document.getElementById('evening').onclick=()=>time('evening');
function move(){hero.style.left=x+'%';near=Math.round((x-13)/24);near=Math.max(0,Math.min(3,near));const close=Math.abs(x-(13+near*24))<7;prompt.hidden=!close;prompt.style.left=(13+near*24)+'%';document.getElementById('feedback').textContent=close?names[near]+' 앞 · E로 확인':'A / D로 장소 앞으로 이동';}
function interact(){if(!prompt.hidden)document.getElementById('feedback').textContent=names[near]+' · '+['성벽 수리','병력 모집·보충','함정 구매·설치','다음 전투'][near]+' 그림 확인 (게임 기능 미연결)';}
names.forEach((n,i)=>{let b=document.createElement('button');b.textContent=n;b.onclick=()=>{x=13+i*24;move();interact()};document.getElementById('places').appendChild(b)});
window.addEventListener('keydown',e=>{if(e.target.matches('button,input,textarea,select'))return;const k=e.key.toLowerCase();if(['a','d','e'].includes(k)){e.preventDefault();held[k]=true;if(k==='e'&&!e.repeat)interact();}});window.addEventListener('keyup',e=>held[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>held={});let last=0;function tick(t){const dt=Math.min((t-last)/1000,.05);last=t;if(held.a||held.d){x=Math.max(5,Math.min(95,x+((held.d?1:0)-(held.a?1:0))*15*dt));move();}requestAnimationFrame(tick)}requestAnimationFrame(tick);
function result(s){document.getElementById('castle').src=A['result/codex_castle_'+(s==='defeat'?'defeat':'example')+'.svg'];document.getElementById('castle').alt=s==='defeat'?'북 금감, 동 남 멀쩡, 서 부서짐':'북 서 금감, 동 남 멀쩡';document.getElementById('resultCaption').textContent=s==='defeat'?'예시 · 북 금감 / 서 부서짐 · 병력 손실 22명':'예시 · 북 금감 / 서 금감 · 병력 손실 22명';document.getElementById('ribbon').src=A['ui/codex_ribbon_'+s+'.svg'];document.getElementById('ribbon').alt=s==='victory'?'승리':'패배';['victory','defeat'].forEach(n=>document.getElementById(n).setAttribute('aria-pressed',n===s));document.getElementById('resultFeedback').textContent=s==='defeat'?'패배 띠 비교용입니다. 패배 결과 진입 흐름은 미확정입니다.':'승리 결과 배치 예시입니다. 실제 결과 데이터와 연결하지 않았습니다.';}document.getElementById('victory').onclick=()=>result('victory');document.getElementById('defeat').onclick=()=>result('defeat');document.getElementById('confirm').onclick=()=>document.getElementById('resultFeedback').textContent='그림 확인 예시입니다. 화면 전환·저장은 실행하지 않습니다.';
